package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class LegacyFinanceMailFilesTest {
 @TempDir Path root;
 @Test void sameOriginalNameGetsIndependentImmutableSnapshots()throws Exception{var files=new LegacyFinanceMailFiles(root.toRealPath().toString());byte[] first="%PDF-one".getBytes(StandardCharsets.US_ASCII),second="%PDF-two".getBytes(StandardCharsets.US_ASCII);var a=files.save("中文账单",first);var b=files.save("中文账单",second);assertEquals("中文账单.pdf",a.get("filename"));assertNotEquals(a.get("path"),b.get("path"));assertArrayEquals(first,files.read(a));assertArrayEquals(second,files.read(b));}
 @Test void invalidNamesTraversalAndSymlinksCannotReadOutsideStorage()throws Exception{var files=new LegacyFinanceMailFiles(root.toRealPath().toString());for(String title:new String[]{"../other","a/b","a\\b","bad\rname","a".repeat(260)})assertEquals(400,assertThrows(BusinessException.class,()->files.save(title,"%PDF-test".getBytes())).getCode());assertEquals(409,assertThrows(BusinessException.class,()->files.read(Map.of("path","../outside.pdf","sha256","x"))).getCode());var a=files.save("owned","%PDF-test".getBytes());Path target=root.resolve(a.get("path").toString());Files.delete(target);Path outside=root.resolve("outside.pdf");Files.writeString(outside,"%PDF-test");Files.createSymbolicLink(target,outside);assertEquals(409,assertThrows(BusinessException.class,()->files.read(a)).getCode());}
}
